contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept arbitrary inputs: from, caddress, _tos array, and value v.
    // The rule: if c.transfer(...) does not revert then it must return true.
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);

        bool reverted;
        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // General rule: when call does not revert, it must return true.
        assert(reverted || ret == true);
    }

    receive() external payable {}
}

