contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The test ensures: for any non-empty _tos, calling transfer either reverts or returns true.
    // We keep parameters simple and require _tos.length > 0 to satisfy the contract's require.
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);

        bool reverted;
        bool returnedTrue;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            returnedTrue = r;
        } catch {
            reverted = true;
            returnedTrue = false;
        }

        // General rule: for any inputs with non-empty _tos, transfer either reverts or returns true.
        assert(reverted || returnedTrue);
    }

    receive() external payable {}
}
